"""Render the Home Assistant package (rest_command + template sensors + automations)."""
from __future__ import annotations

import json

from .mapping import (
    HA_TO_LOXONE,
    LOXONE_TO_HA,
    NUMBER_DOMAINS,
    BridgeMapping,
    DerivedSensor,
    Point,
)

HEADER = (
    "# Generated by tools.ha_loxone_bridge — do not edit by hand, change the mapping file and regenerate.\n"
    "# Use as an HA package (homeassistant: packages: !include_dir_named packages).\n"
    "# Needs secrets.yaml entries: {user}, {password}.\n"
)


def _q(text: str) -> str:
    """YAML double-quoted scalar (JSON string syntax is valid YAML)."""
    return json.dumps(text, ensure_ascii=False)


def _jinja(expr: str) -> str:
    return "{{ " + expr + " }}"


def _num(value: float) -> str:
    return str(int(value)) if float(value).is_integer() else repr(float(value))


def rest_command_name(point: Point) -> str:
    return f"loxone_push_{point.name}"


def _loxone_base(mapping: BridgeMapping) -> str:
    port = "" if mapping.loxone_port == 80 else f":{mapping.loxone_port}"
    return f"http://{mapping.loxone_host}{port}"


def _render_rest_commands(mapping: BridgeMapping) -> list[str]:
    out = ["rest_command:"]
    for p in mapping.points:
        if p.direction != HA_TO_LOXONE:
            continue
        url = f"{_loxone_base(mapping)}/jdev/sps/io/{p.loxone_name}/{{{{ value }}}}"
        out += [
            f"  {rest_command_name(p)}:",
            f"    url: {_q(url)}",
            f"    username: !secret {mapping.loxone_user_secret}",
            f"    password: !secret {mapping.loxone_pass_secret}",
        ]
    return out


def _derived_state(d: DerivedSensor) -> str:
    expr = " + ".join(f"states('{e}') | float" for e in d.plus)
    # Jinja filters bind tighter than + / -, so no parentheses are needed per term.
    for e in d.minus:
        expr += f" - states('{e}') | float"
    return _jinja(expr)


def _derived_availability(d: DerivedSensor) -> str:
    checks = " and ".join(f"states('{e}') | is_number" for e in (*d.plus, *d.minus))
    return _jinja(checks)


def _render_derived(mapping: BridgeMapping) -> list[str]:
    if not mapping.derived:
        return []
    out = ["template:", "  - sensor:"]
    for d in mapping.derived:
        out += [
            f"      - name: {_q(d.name)}",
            f"        unique_id: {d.entity_id.split('.', 1)[1]}",
            f"        unit_of_measurement: {_q(d.unit)}",
        ]
        if d.device_class:
            out.append(f"        device_class: {d.device_class}")
        if d.state_class:
            out.append(f"        state_class: {d.state_class}")
        out += [
            f"        state: {_q(_derived_state(d))}",
            f"        availability: {_q(_derived_availability(d))}",
        ]
    return out


def _automation_head(mapping: BridgeMapping, p: Point, arrow: str, *, mode: str = "queued") -> list[str]:
    out = [
        f"  - id: ha_loxone_bridge_{p.name}",
        f"    alias: {_q(f'{mapping.title}: {p.name} {arrow}')}",
        '    description: "Generated by tools.ha_loxone_bridge"',
        f"    mode: {mode}",
    ]
    if mode == "queued":
        out.append("    max: 5")
    return out


def _render_push_automation(mapping: BridgeMapping, p: Point) -> list[str]:
    ent = p.ha_entity
    is_num = f"states('{ent}') | is_number"
    as_float = f"states('{ent}') | float"
    out = _automation_head(mapping, p, "-> Loxone")
    out += [
        "    triggers:",
        "      - trigger: state",
        f"        entity_id: {ent}",
        # Re-push after an HA restart; the Miniserver keeps the last value but resets on its own reboot.
        "      - trigger: homeassistant",
        "        event: start",
    ]
    if p.refresh_minutes:
        out += ["      - trigger: time_pattern", f"        minutes: {_q(f'/{p.refresh_minutes}')}"]
    out += [
        "    conditions:",
        "      - condition: template",
        f"        value_template: {_q(_jinja(is_num))}",
        "    actions:",
        f"      - action: rest_command.{rest_command_name(p)}",
        "        data:",
        f"          value: {_q(_jinja(as_float))}",
    ]
    return out


def _target_expr(p: Point) -> str:
    expr = "trigger.query.v | float"
    if p.step is not None:
        expr = f"(({expr}) / {_num(p.step)}) | round(0) * {_num(p.step)}"
    if p.minimum is not None:
        expr = f"[ {expr}, {_num(p.minimum)} ] | max"
    if p.maximum is not None:
        expr = f"[ {expr}, {_num(p.maximum)} ] | min"
    return _jinja(expr)


def _webhook_trigger(mapping: BridgeMapping, p: Point) -> list[str]:
    return [
        "      - trigger: webhook",
        "        id: webhook",
        f"        webhook_id: {p.webhook_id}",
        "        allowed_methods: [GET]",
        f"        local_only: {'true' if mapping.webhook_local_only else 'false'}",
    ]


def _render_number_webhook_automation(mapping: BridgeMapping, p: Point) -> list[str]:
    ent = p.ha_entity
    differs = f"states('{ent}') | float(none) != target"
    out = _automation_head(mapping, p, "<- Loxone")
    out += [
        "    triggers:",
        *_webhook_trigger(mapping, p),
        "    conditions:",
        "      - condition: template",
        f"        value_template: {_q('{{ trigger.query.v is defined and (trigger.query.v | is_number) }}')}",
        "    actions:",
        "      - variables:",
        f"          target: {_q(_target_expr(p))}",
        # Loxone repeats the command: only touch the device when the value differs (cloud rate limits).
        "      - condition: template",
        f"        value_template: {_q(_jinja(differs))}",
        f"      - action: {NUMBER_DOMAINS[p.domain]}",
        "        target:",
        f"          entity_id: {ent}",
        "        data:",
        f"          value: {_q('{{ target }}')}",
    ]
    return out


def _render_switch_webhook_automation(mapping: BridgeMapping, p: Point) -> list[str]:
    """Loxone sends On repeatedly and Off once on the edge; a missing On counts as Off.

    ``mode: restart``: every On restarts the run and with it the off timer. When the timer runs out
    (On stopped arriving: lost Off call, link down, Loxone gone) the switch goes off and a warning is
    logged. After an HA start the timer runs right away, so an Off missed during the restart still applies.
    """
    ent, domain = p.ha_entity, p.domain
    is_on = f"is_state('{ent}', 'on')"
    want_on = "trigger.id == 'webhook' and (trigger.query.v | float) >= 0.5"
    start_timer = "want_on or trigger.id == 'start'"
    message = f"{mapping.title}: no On from Loxone for {p.off_after_seconds} s, switching {ent} off"
    out = _automation_head(mapping, p, "<- Loxone", mode="restart")
    out += [
        "    triggers:",
        *_webhook_trigger(mapping, p),
        "      - trigger: homeassistant",
        "        id: start",
        "        event: start",
        "    conditions:",
        "      - condition: template",
        "        value_template: "
        + _q("{{ trigger.id == 'start' or (trigger.query.v is defined and (trigger.query.v | is_number)) }}"),
        "    actions:",
        "      - variables:",
        f"          want_on: {_q(_jinja(want_on))}",
        # Only touch the device when the state differs (cloud rate limits, relay wear).
        "      - if:",
        "          - condition: template",
        f"            value_template: {_q(_jinja(f'want_on and not {is_on}'))}",
        "        then:",
        f"          - action: {domain}.turn_on",
        "            target:",
        f"              entity_id: {ent}",
        "      - if:",
        "          - condition: template",
        f"            value_template: {_q(_jinja(start_timer))}",
        "        then:",
        "          - delay:",
        f"              seconds: {p.off_after_seconds}",
        "          - if:",
        "              - condition: template",
        f"                value_template: {_q(_jinja(is_on))}",
        "            then:",
        "              - action: system_log.write",
        "                data:",
        "                  level: warning",
        "                  logger: ha_loxone_bridge",
        f"                  message: {_q(message)}",
        "      - if:",
        "          - condition: template",
        f"            value_template: {_q(_jinja(is_on))}",
        "        then:",
        f"          - action: {domain}.turn_off",
        "            target:",
        f"              entity_id: {ent}",
    ]
    return out


def render_package(mapping: BridgeMapping) -> str:
    lines = HEADER.format(user=mapping.loxone_user_secret, password=mapping.loxone_pass_secret).splitlines()
    blocks = [_render_rest_commands(mapping) if any(p.direction == HA_TO_LOXONE for p in mapping.points) else [],
              _render_derived(mapping)]
    automations: list[str] = ["automation:"]
    for p in mapping.points:
        if p.direction == HA_TO_LOXONE:
            automations += _render_push_automation(mapping, p)
        elif p.direction == LOXONE_TO_HA and p.is_switch:
            automations += _render_switch_webhook_automation(mapping, p)
        elif p.direction == LOXONE_TO_HA:
            automations += _render_number_webhook_automation(mapping, p)
    blocks.append(automations)
    for block in blocks:
        if block:
            lines += ["", *block]
    return "\n".join(lines) + "\n"
